$pdo=db(); $error=''; $notice='';
$admin=ekAdmin();
if($_SERVER['REQUEST_METHOD']==='POST'){
 verify(); $action=(string)($_POST['action']??'save'); $id=(int)($_POST['id']??0);
 try {
  if($action==='delete')throw new RuntimeException('Kalıcı silme için kayıt satırındaki silme incelemesini kullanın.');
  if($action!=='save')throw new RuntimeException('Geçersiz işlem.');
  $type=($_POST['type']??'')==='company'?'company':'individual';
  $name=trim((string)($_POST['name']??''));$company=trim((string)($_POST['company']??''));$email=trim((string)($_POST['email']??''));$phone=trim((string)($_POST['phone']??''));$address=trim((string)($_POST['address']??''));
  if($name===''||mb_strlen($name)>190)throw new RuntimeException('Müşteri adı zorunlu ve en fazla 190 karakter olmalıdır.');
  if(mb_strlen($company)>190||mb_strlen($email)>190||mb_strlen($phone)>50)throw new RuntimeException('Bir veya daha fazla alan çok uzun.');
  if($email!==''&&!filter_var($email,FILTER_VALIDATE_EMAIL))throw new RuntimeException('E-posta adresi geçersiz.');
  if($id){$pdo->beginTransaction();ekLockCustomerForUpdate($pdo,$id,$name,$company);$s=$pdo->prepare('UPDATE customers SET type=?,name=?,company=?,email=?,phone=?,address=? WHERE id=?');$s->execute([$type,$name,$company,$email,$phone,$address,$id]);$pdo->commit();redirect('customers.php?result=updated');}
  $s=$pdo->prepare('INSERT INTO customers(type,name,company,email,phone,address) VALUES (?,?,?,?,?,?)');$s->execute([$type,$name,$company,$email,$phone,$address]);redirect('customers.php?result=created');
 }catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();$error=$e->getMessage();}
}
$editId=(int)($_GET['edit']??0);$editing=null;
if($editId){$s=$pdo->prepare('SELECT * FROM customers WHERE id=?');$s->execute([$editId]);$editing=$s->fetch();if(!$editing)$error='Düzenlenecek müşteri bulunamadı.';}
$search=trim((string)($_GET['q']??''));$filter=(string)($_GET['type']??'all');if(!in_array($filter,['all','individual','company'],true))$filter='all';
$page=max(1,(int)($_GET['page']??1));$perPage=15;
$archived=(($_GET['archived']??'')==='1');
$where=[ekCustomerArchiveCondition().($archived?'=1':'=0')];$args=[];
if($search!==''){$where[]='(c.name LIKE ? OR c.company LIKE ? OR c.email LIKE ? OR c.phone LIKE ?)';$term='%'.$search.'%';$args=array_merge($args,[$term,$term,$term,$term]);}
if($filter!=='all'){$where[]='c.type=?';$args[]=$filter;}
$condition=$where?' WHERE '.implode(' AND ',$where):'';
$cnt=$pdo->prepare('SELECT COUNT(*) FROM customers c'.$condition);$cnt->execute($args);$total=(int)$cnt->fetchColumn();$pages=max(1,(int)ceil($total/$perPage));$page=min($page,$pages);$offset=($page-1)*$perPage;
$sql='SELECT c.*, (SELECT COUNT(*) FROM quotes q WHERE q.customer_id=c.id) AS quote_count, (SELECT MAX(q.created_at) FROM quotes q WHERE q.customer_id=c.id) AS last_quote FROM customers c'.$condition.' ORDER BY c.id DESC LIMIT '.(int)$perPage.' OFFSET '.(int)$offset;
$stmt=$pdo->prepare($sql);$stmt->execute($args);$rows=$stmt->fetchAll();
$stats=$pdo->query('SELECT COUNT(*) AS total, COALESCE(SUM(type="individual"),0) AS individual_count, COALESCE(SUM(type="company"),0) AS company_count FROM customers')->fetch();
$withQuotes=(int)$pdo->query('SELECT COUNT(DISTINCT customer_id) FROM quotes')->fetchColumn();
function customerLink($page,$search,$filter){return 'customers.php?'.http_build_query(['q'=>$search,'type'=>$filter,'page'=>$page,'archived'=>(($_GET['archived']??'')==='1')?1:0]);}
top('Müşteriler');
